//! ML-DSA-44 instantiation (FIPS 204 §4 Table 1).
//!
//! Parameters: λ=128, τ=39, γ₁=2¹⁷, γ₂=(q−1)/88, k=4, ℓ=4, η=2, β=78, ω=80.
//! Sizes: PK_LEN=1312, SK_LEN=2560, SIG_LEN=2420, CTILDE_LEN=32.
//!
//! Generated by the `ml_dsa_impl!` macro.
//!
//! # CNSA gating
//!
//! ML-DSA-44 is **not** part of CNSA 2.0 (which mandates ML-DSA-87)
//! and is **not** in the CNSA 1.0 suite. The
//! `Service::MlDsa44Sign` / `Verify` / `Keygen` variants are
//! permitted only under [`oxicrypt_module::AlgorithmProfile::Unrestricted`].
//! See `crates/oxicrypt-module/src/lib.rs` `is_cnsa1_allowed` and
//! `is_cnsa2_allowed` — neither extends to ML-DSA-44.

#![allow(
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::cast_possible_truncation,
    clippy::cast_lossless,
    clippy::cast_possible_wrap,
    clippy::cast_sign_loss,
    clippy::similar_names,
    clippy::many_single_char_names,
    clippy::needless_range_loop,
    clippy::integer_division,
    clippy::too_many_lines,
    dead_code
)]

crate::ml_dsa_impl::ml_dsa_impl! {
    lambda = 128;
    tau = 39;
    gamma1 = 1 << 17;
    gamma2 = (8_380_417 - 1) / 88;
    k = 4;
    l = 4;
    eta = 2;
    beta = 78;
    omega = 80;
    svc_keygen = Service::MlDsa44Keygen;
    svc_sign = Service::MlDsa44Sign;
    svc_verify = Service::MlDsa44Verify;
}

#[cfg(test)]
#[allow(
    clippy::unwrap_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]
mod tests {
    use super::*;

    #[test]
    fn key_sizes_match_spec() {
        crate::test_support::start_module();
        assert_eq!(PK_LEN, 1312);
        assert_eq!(SK_LEN, 2560);
        assert_eq!(SIG_LEN, 2420);
        assert_eq!(CTILDE_LEN, 32);
    }

    #[test]
    fn parameter_constants_match_spec() {
        crate::test_support::start_module();
        assert_eq!(K, 4);
        assert_eq!(L, 4);
        assert_eq!(ETA, 2);
        assert_eq!(TAU, 39);
        assert_eq!(BETA, 78);
        assert_eq!(OMEGA, 80);
    }

    #[test]
    fn round_trip_basic() {
        crate::test_support::start_module();
        let xi = [0x42u8; 32];
        let (pk, sk) = keygen_internal(&xi).unwrap();
        let msg = b"hello, ML-DSA-44";
        let sig = sign_internal(&sk, msg).unwrap();
        assert!(verify_internal(&pk, msg, &sig).unwrap());
    }

    #[test]
    fn wrong_message_rejected() {
        crate::test_support::start_module();
        let xi = [0x01u8; 32];
        let (pk, sk) = keygen_internal(&xi).unwrap();
        let sig = sign_internal(&sk, b"original").unwrap();
        assert!(!verify_internal(&pk, b"tampered", &sig).unwrap());
    }

    #[test]
    fn tampered_signature_rejected() {
        crate::test_support::start_module();
        let xi = [0x55u8; 32];
        let (pk, sk) = keygen_internal(&xi).unwrap();
        let msg = b"test message";
        let mut sig = sign_internal(&sk, msg).unwrap();
        sig[50] ^= 0xFF;
        assert!(!verify_internal(&pk, msg, &sig).unwrap());
    }
}
